(() => {
  'use strict';
  const {units, areas} = window.COURSE;
  const E = window.EVIDENCE;
  const KEY = 'calapa-course-v2';
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon = name => `<i data-lucide="${name}" aria-hidden="true"></i>`;
  const table = (headers,rows) => `<div class="table-scroll"><table><thead><tr>${headers.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td${/^[-+]?\d+(?:\.\d+)?%?$|^\d+ \/ \d+$/.test(String(x))?' class="number"':''}>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const f = (value,digits=1) => value === null || value === undefined || !Number.isFinite(Number(value)) ? 'Not reported' : Number(value).toFixed(digits);
  let state = {size:18,area:'start',mode:'lecture',notes:{},checks:{}};
  let storageAvailable = true;
  try { const saved = JSON.parse(localStorage.getItem(KEY) || 'null'); if(saved && typeof saved === 'object') state={...state,...saved,notes:saved.notes||{},checks:saved.checks||{}}; } catch {storageAvailable=false;}
  if(![16,18,21].includes(state.size)) state.size=18;
  if(!areas.some(a=>a.id===state.area)) state.area='start';
  if(!['lecture','walkthrough'].includes(state.mode)) state.mode='lecture';
  const main=document.querySelector('#main'), sidebar=document.querySelector('#sidebar');
  const actions=document.createElement('div');actions.className='header-actions';
  const themeButton=document.createElement('button');themeButton.id='themeBtn';themeButton.className='icon-button theme-switch';themeButton.type='button';
  actions.append(themeButton,document.querySelector('#menuBtn'));document.querySelector('.topbar').append(actions);
  function themeLabel(){const dark=document.documentElement.dataset.theme==='dark';themeButton.title=dark?'Switch to light theme':'Switch to dark theme';themeButton.setAttribute('aria-label',themeButton.title);themeButton.innerHTML=icon(dark?'sun':'moon');window.lucide?.createIcons();}
  themeButton.addEventListener('click',()=>{window.setMentorTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');themeLabel();});
  themeLabel();
  let toastTimer, currentUnit=null, lastRoute='';
  function notify(message){const el=document.querySelector('#status');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2800);}
  function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{storageAvailable=false;notify('Browser storage is unavailable. Export your notes before leaving.');return false;}}
  function route(id,mode=state.mode){return `#unit/${id}/${mode}`;}
  function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  const charts={
    'graduation-trend':{title:'Graduation across available years',file:'graduation-trend.png',key:'graduation_trend',caption:'Jordan High schoolwide graduation, reporting years 2021-2025. The connected line displays reported values; it does not establish a comparable causal trend. Check historical measure definitions and DASS variants.',headers:['Reporting year','Graduates','Accountability denominator','Rate (%)','Fifth-year graduates','Source file'],rows:r=>[r.reporting_year,f(r.graduates,0),r.cohort_students,f(r.graduation_rate),r.five_year_graduates,r.source_file]},
    'graduation-comparison':{title:'Graduation in school, district, and state',file:'graduation-comparison.png',key:'graduation_comparison',caption:'Reporting year 2025. Jordan High 85.9%; Los Angeles Unified 86.5%; California 87.8%. These broad reference populations are not matched comparison groups.',headers:['Level','Graduates','Accountability denominator','Rate (%)','Source file'],rows:r=>[r.level,f(r.graduates,0),r.cohort_students,f(r.graduation_rate),r.source_file]},
    'graduation-gaps':{title:'Graduation subgroup gaps',file:'graduation-gaps.png',key:'graduation_gaps',gap:true,caption:'Reporting year 2025. The zero line marks the schoolwide rate of 85.9%; it does not mean zero graduation. Bars show percentage-point differences. English Learners: 70.8%, 46 graduates / 65 in the accountability denominator. Groups overlap and cannot be added together.',headers:['Student group','Graduates','Denominator','Rate (%)','Gap (points)','Count note'],rows:r=>[r.student_group_label,f(r.graduates,0),r.cohort_students,f(r.graduation_rate),f(r.gap_from_schoolwide),r.cohort_students<30?'Small group; descriptive caution':'']},
    'attendance-trend':{title:'Attendance as supporting context',file:'attendance-trend.png',key:'attendance_trend',caption:'Jordan High DataQuest chronic absenteeism across available school years. Higher rates indicate greater concern. This high-school measure is not the TK-8 Dashboard Chronic Absenteeism Indicator.',headers:['School year','Chronically absent','Eligible students','Rate (%)','Source file'],rows:r=>[r.academic_year,r.chronic_absenteeism_count,r.eligible_enrollment,f(r.chronic_absenteeism_rate),r.source_file]},
    'attendance-gaps':{title:'Attendance subgroup gaps',file:'attendance-gaps.png',key:'attendance_gaps',gap:true,caption:'School year 2024-25. The zero line marks the schoolwide chronic absenteeism rate of 49.1%. Positive gaps mean higher absenteeism. Single-category groups overlap; these are not intersectional results.',headers:['Student group','Chronically absent','Eligible students','Rate (%)','Gap (points)','Count note'],rows:r=>[r.student_group,r.chronic_absenteeism_count,r.eligible_enrollment,f(r.chronic_absenteeism_rate),f(r.gap_from_schoolwide),r.eligible_enrollment<30?'Small group; descriptive caution':'']},
    'ela-trend':{title:'ELA across available years',file:'ela-trend.png',key:'ela_trend',valueField:'standard_met_or_exceeded_percent',caption:'Schoolwide Smarter Balanced ELA percent meeting or exceeding standard across available school years. The denominator is valid scores, not enrollment. These are annual reported groups, not repeated observations of the same students.',qualifiers:'This measure is not Dashboard Distance from Standard. Grade code 13 is the source all-tested-grades aggregate; check the actual grades represented. The chart does not establish a teaching effect.',headers:['School year','Enrolled','Tested','Valid scores','Met/exceeded (%)','Source member'],rows:r=>[r.academic_year,r.enrolled_count,r.tested_count,r.valid_score_count,f(r.standard_met_or_exceeded_percent),r.source_member]},
    'math-trend':{title:'Math across available years',file:'math-trend.png',key:'math_trend',valueField:'standard_met_or_exceeded_percent',caption:'Schoolwide Smarter Balanced Math percent meeting or exceeding standard across available school years. Keep the subject-specific valid-score denominator. These results do not identify which instructional practice explains the pattern.',qualifiers:'This measure is not Dashboard Distance from Standard. Check source-year grade composition, participation, and valid-score counts. ELA and Math denominators need not match.',headers:['School year','Enrolled','Tested','Valid scores','Met/exceeded (%)','Source member'],rows:r=>[r.academic_year,r.enrolled_count,r.tested_count,r.valid_score_count,f(r.standard_met_or_exceeded_percent),r.source_member]},
    'suspension-comparison':{title:'Suspension system comparison',file:'suspension-comparison.png',key:'suspension_comparison',valueField:'suspension_rate',caption:'Reported suspension rates for 2025: school, district, and state. Lower suspension rates do not by themselves establish equitable discipline or a positive school climate.',qualifiers:'The denominator is cumulative enrollment. Retain certification and data-error flags. Uncertified or unavailable values are not ordinary zeros; these system averages are not matched controls.',headers:['Level','Suspended students','Cumulative enrollment','Rate (%)','Certification flag','Data-error flag','Source file'],rows:r=>[r.level,r.suspended_students,r.cumulative_enrollment,f(r.suspension_rate),r.certify_flag??'Not reported',r.data_error_flag??'Not reported',r.source_file]},
    'elpi-trend':{title:'English learner progress across available years',file:'elpi-trend.png',key:'elpi_trend',valueField:'rate',caption:'School English Learners ELPI, reporting years 2019 and 2022-2025. Only available years are shown. The line is a display of reported values, not evidence of comparable annual growth or an effect of a teacher or program.',qualifiers:'The 2019-2023 source layouts contain historical EL aggregates without a student-group field. Accountability denominators can contain participation adjustments, not observed tested students who failed to progress. A missing adjustment is not zero. These records are transcribed from the saved ELPI timeline, Table 2.',headers:['Reporting year','Numerator','Accountability denominator','ELPI (%)','Current participation additions','Source qualification'],rows:r=>[r.reporting_year,r.numerator,r.denominator,f(r.rate),r.participation_additions??'Not reported',r.source_qualification]}
  };
  function chartHTML(id){
    const c=charts[id]; if(!c)return '';
    const qualifiers=c.qualifiers||(id.startsWith('graduation')?'The 2024-2025 records use the Dashboard combined four-/five-year accountability measure. The denominator is not all fifth-year students. Historical years need source-specific interpretation.':'The 2020-21 attendance source did not collect DASS status; its stored value is not an observed classification. Missing and suppressed rates are not zero.');
    return `<figure class="chart ${c.gap?'gap':''}"><img src="assets/${c.file}" alt="${esc(c.caption)}" width="1200" ${c.gap?'':'height="700"'}><div class="chart-toolbar"><span>Equity Gap app figure &middot; Jordan High</span><div class="chart-actions"><button class="icon-button" data-zoom="${id}" title="Enlarge chart" aria-label="Enlarge ${esc(c.title)}">${icon('maximize-2')}</button><a href="assets/${c.file}" download title="Download chart PNG" aria-label="Download ${esc(c.title)} PNG">${icon('image-down')}</a><a href="sources/${c.key}.csv" download title="Download source table CSV" aria-label="Download ${esc(c.title)} table">${icon('file-down')}</a></div></div><figcaption>${c.caption}</figcaption><details><summary>View the figures, denominators, and source notes</summary>${table(c.headers,E[c.key].map(c.rows))}<p class="source-note">${qualifiers} Small-group warnings use the source app's n&lt;30 review heuristic, not a significance test or a CalAPA cutoff.</p><p class="source-note">Snapshot saved October 6, 2026, for Jordan High (CDS 19647331934454). The Equity Gap app produced this chart from its stored public data; saving it did not re-check every CDE source record. <a href="sources/${c.key}.csv" download>Full table and source fields</a>.</p></details></figure>`;
  }
  function historyHTML(){return table(['Reporting year','English Learners graduates / denominator','EL rate','Schoolwide graduates / denominator','Schoolwide rate','Gap (points)'],E.graduation_el_history.map(r=>{const s=E.graduation_trend.find(x=>x.reporting_year===r.reporting_year);return [r.reporting_year,`${f(r.graduates,0)} / ${r.cohort_students}`,`${f(r.graduation_rate)}%`,`${f(s.graduates,0)} / ${s.cohort_students}`,`${f(s.graduation_rate)}%`,f(r.gap_from_schoolwide)];}))+`<p class="source-note">Source files: graddownload2023.txt, graddownload2024.txt, graddownload2025.txt. Schoolwide includes English Learners. The 2023 historical measure/DASS variant needs verification before a like-for-like change claim; 2024-2025 use the combined four-/five-year accountability measure. Values are source-reported, rounded rates. <a href="sources/graduation_el_history.csv" download>Download subgroup records</a>.</p>`;}
  function hydrate(){
    document.querySelectorAll('[data-chart]').forEach(el=>el.innerHTML=chartHTML(el.dataset.chart));
    document.querySelectorAll('[data-history-table]').forEach(el=>el.innerHTML=historyHTML());
    document.querySelectorAll('.chart').forEach(el=>{
      const id=el.querySelector('[data-zoom]')?.dataset.zoom;
      if(id)el.insertAdjacentHTML('beforeend',`<p class="source-note">Use official California sources to verify the figures. You can begin exploring patterns in the <a href="https://explorer.chrisboosalis.com" target="_blank" rel="noreferrer">Equity Gap app</a>; check its values against the official source before using them.</p>`);
    });
    window.lucide?.createIcons();
  }
  let builderState=null;
  function initialBuilder(id){
    const c=charts[id]||charts['graduation-trend'];
    const gap=!!c.gap,attendance=c.key.startsWith('attendance');
    const rows=E[c.key].slice(0,12).map(r=>({label:String(r.student_group_label??r.student_group??r.level??r.academic_year??r.reporting_year),value:gap?r.gap_from_schoolwide:c.valueField?r[c.valueField]:attendance?r.chronic_absenteeism_rate:r.graduation_rate}));
    return {id:charts[id]?id:'graduation-trend',title:c.title,kind:c.key.endsWith('trend')?'line':'bar',gap,rows,edited:false,generated:false};
  }
  function builder(id){
    id=charts[id]?id:'graduation-trend';if(!builderState||builderState.id!==id)builderState=initialBuilder(id);
    const b=builderState;
    main.innerHTML=`<p class="kicker">Evidence builder</p><h1>Create a table and chart</h1><p class="deck">Generate the same kinds of numerical evidence tables and charts used in the examples.</p><div class="builder-controls"><label>Example<select id="builderExample">${Object.entries(charts).map(([key,c])=>`<option value="${key}" ${key===id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label><label>Chart title<input id="builderTitle" maxlength="90" value="${esc(b.title)}"></label><label>Chart type<select id="builderKind"><option value="bar" ${b.kind==='bar'?'selected':''}>Horizontal bars</option><option value="line" ${b.kind==='line'?'selected':''}>Line</option></select></label></div><p class="note">Stored public-data example, prepared October 6, 2026. ${b.gap?'Values are percentage-point gaps. Zero is the schoolwide reference, not a zero rate.':'Values are rates from 0 to 100 percent.'} Use aggregate data only. Blank values stay missing. Inputs remain in this browser session and are not uploaded or saved.</p><div class="table-scroll"><table class="builder-inputs"><thead><tr><th scope="col">Category / year</th><th scope="col">${b.gap?'Gap (points)':'Rate (%)'}</th><th scope="col">Remove</th></tr></thead><tbody>${b.rows.map((r,i)=>`<tr><td><input data-builder-label="${i}" aria-label="Category ${i+1}" maxlength="80" value="${esc(r.label)}"></td><td><input data-builder-value="${i}" aria-label="Value ${i+1}" type="number" min="${b.gap?-100:0}" max="100" step="any" value="${r.value===null?'':r.value}"></td><td><button class="icon-button" data-builder-remove="${i}" aria-label="Remove row ${i+1}" title="Remove row ${i+1}" ${b.rows.length===1?'disabled':''}>${icon('trash-2')}</button></td></tr>`).join('')}</tbody></table></div><div class="tools"><button data-builder-add ${b.rows.length>=12?'disabled':''}>${icon('plus')} Add row</button><button data-builder-generate>${icon('chart-no-axes-combined')} Generate table and chart</button><button data-builder-reset>${icon('rotate-ccw')} Reset example</button></div><p id="builderError" class="builder-error" role="status"></p><section id="builderOutput" aria-label="Generated evidence" hidden></section><p class="source-note">${esc(charts[id].caption)} <a href="#charts/${id}">Original figure, denominators, and source notes</a>. Editing values does not verify their accuracy, recompute rates from counts, or establish causation.</p>`;
    document.querySelector('#builderKind option[value="line"]').disabled=!id.endsWith('trend');
    if(b.generated)generateEvidence();
  }
  function dirtyBuilder(){builderState.edited=true;builderState.generated=false;document.querySelector('#builderOutput').hidden=true;document.querySelector('#builderError').textContent='Changes not generated yet.';}
  function generateEvidence(){
    const b=builderState,error=document.querySelector('#builderError');
    if(!b.title.trim()||b.rows.some(r=>!r.label.trim())){error.textContent='Enter a title and a label for every row.';return;}
    if(b.rows.some(r=>r.value!==null&&(!Number.isFinite(r.value)||r.value<(b.gap?-100:0)||r.value>100))){error.textContent=`Enter ${b.gap?'-100':'0'} to 100, or leave a value blank.`;return;}
    if(!b.rows.some(r=>r.value!==null)){error.textContent='Enter at least one numeric value. A blank is not zero.';return;}
    error.textContent='';b.generated=true;
    const output=document.querySelector('#builderOutput');output.hidden=false;
    output.innerHTML=`<h2>${esc(b.title)}</h2><p class="builder-caption">${b.edited?'User-entered aggregate values. Not independently verified.':'Stored public-data example. Source definitions and cohort comparability still apply.'} ${b.gap?'Percentage-point differences from the schoolwide rate.':'Reported rates (%).'} Missing values are not plotted.</p><div class="generated-chart"><canvas id="generatedCanvas" role="img" aria-label="${esc(b.title)}. Exact values appear in the table below."></canvas></div>${table(['Category / year',b.gap?'Gap (points)':'Rate (%)'],b.rows.map(r=>[r.label,r.value===null?'Not reported':f(r.value)]))}<div class="tools"><button class="icon-button" data-builder-png title="Download generated chart PNG" aria-label="Download generated chart PNG">${icon('image-down')}</button><button class="icon-button" data-builder-csv title="Download generated table CSV" aria-label="Download generated table CSV">${icon('file-down')}</button></div>`;
    const canvas=document.querySelector('#generatedCanvas');canvas.width=1200;canvas.height=b.kind==='bar'?Math.max(420,190+b.rows.length*68):660;
    const ctx=canvas.getContext('2d'),W=canvas.width,H=canvas.height;
    ctx.fillStyle='#ffffff';ctx.fillRect(0,0,W,H);ctx.fillStyle='#1f2924';ctx.font='bold 25px Arial';ctx.fillText(b.title.length>78?b.title.slice(0,75)+'...':b.title,35,42);
    ctx.font='18px Arial';ctx.fillText(b.gap?'Gap from schoolwide (percentage points)':'Rate (%)',35,73);
    const extent=b.gap?Math.max(5,Math.ceil(Math.max(...b.rows.map(r=>Math.abs(r.value??0)))/5)*5):100;
    const lo=b.gap?-extent:0,hi=extent,tick=b.gap?extent/2:25,left=b.kind==='bar'?335:90,right=1100,top=110,bottom=H-130;
    ctx.strokeStyle='#bac8c0';ctx.lineWidth=1;ctx.font='18px Arial';
    if(b.kind==='bar'){
      const x=v=>left+(v-lo)/(hi-lo)*(right-left),zero=x(0);
      for(let v=lo;v<=hi;v+=tick){ctx.beginPath();ctx.moveTo(x(v),top);ctx.lineTo(x(v),bottom+20);ctx.stroke();ctx.fillStyle='#394c42';ctx.fillText(String(v),x(v)-12,bottom+45);}
      b.rows.forEach((r,i)=>{const y=top+18+i*68;ctx.fillStyle='#25362c';ctx.font='18px Arial';const words=r.label.match(/.{1,31}(?:\s|$)|.{1,31}/g)||[r.label];words.slice(0,3).forEach((s,j)=>ctx.fillText(s.trim(),20,y+8+j*19));if(r.value===null){ctx.fillText('Not reported',zero+8,y+8);return;}const concern=b.id.startsWith('attendance')?r.value>0:r.value<0;ctx.fillStyle=b.gap?(concern?'#9b405b':'#246f54'):'#265a82';ctx.fillRect(Math.min(zero,x(r.value)),y-13,Math.max(2,Math.abs(x(r.value)-zero)),30);ctx.fillStyle='#25362c';ctx.fillText(f(r.value),right+15,y+10);});
    }else{
      const y=v=>bottom-(v-lo)/(hi-lo)*(bottom-top),x=i=>left+i*(right-left)/Math.max(1,b.rows.length-1);
      for(let v=lo;v<=hi;v+=tick){ctx.beginPath();ctx.moveTo(left,y(v));ctx.lineTo(right,y(v));ctx.stroke();ctx.fillStyle='#394c42';ctx.fillText(String(v),30,y(v)+6);}
      let previous=null;ctx.strokeStyle='#246f54';ctx.lineWidth=3;
      b.rows.forEach((r,i)=>{ctx.fillStyle='#25362c';ctx.font='16px Arial';const label=r.label.length>14?r.label.slice(0,11)+'...':r.label;ctx.save();ctx.translate(x(i),bottom+24);ctx.rotate(-Math.PI/7);ctx.fillText(label,-20,0);ctx.restore();if(r.value===null){previous=null;return;}if(previous!==null){ctx.beginPath();ctx.moveTo(x(previous),y(b.rows[previous].value));ctx.lineTo(x(i),y(r.value));ctx.stroke();}ctx.fillStyle='#246f54';ctx.beginPath();ctx.arc(x(i),y(r.value),6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#25362c';ctx.fillText(f(r.value),x(i)-15,y(r.value)-14);previous=i;});
    }
    ctx.font='17px Arial';ctx.fillStyle='#394c42';ctx.fillText(b.edited?'User-entered values; not independently verified.':'Public snapshot, 2026-10-06; consult original source definitions.',35,H-25);window.lucide?.createIcons();
  }
  function sidebarHTML(){
    const selection=areas.find(a=>a.id===state.area);
    const cycle=state.area==='start'?'c1':state.area;
    const navLink=(href,label,symbol,active=location.hash===href)=>`<a class="unit-link" href="${href}" ${active?'aria-current="page"':''}>${icon(symbol)}<span>${label}</span></a>`;
    const stepNames={investigate:'Investigate',plan:'Plan',act:'Act',reflect:'Reflect'};
    const unitLinks=units.filter(u=>u.area===state.area).map(u=>navLink(route(u.id,'lecture'),state.area==='start'?esc(u.title):`${stepNames[u.id.split('-')[1]]}<small>${esc(u.parts)}</small>`,'file-text',u.id===currentUnit?.id)).join('');
    sidebar.innerHTML=`<label for="areaSelect">Choose a cycle</label><select id="areaSelect">${areas.map(a=>`<option value="${a.id}" ${a.id===state.area?'selected':''}>${a.title}</option>`).join('')}</select><h2>${selection.title}</h2><nav class="unit-links" aria-label="Cycle contents">${navLink(state.area==='start'?'#home':`#connections/${cycle}`,'Overview','book-open',state.area==='start'?(!location.hash||location.hash==='#home'):location.hash===`#connections/${cycle}`)}${unitLinks}${navLink(`#gap/${cycle}`,'Working with the Gap app','chart-no-axes-combined')}${state.area!=='start'?navLink(`#literature/${cycle}`,'Using literature','library-big'):''}${['c2','c3'].includes(state.area)?navLink('#recording','Video & commentary','video'):''}${navLink(`#sources/${state.area}`,'Saved Version 09 templates','files')}${state.area==='start'?navLink('#home/common-thread','A Common Thread','git-merge'):''}</nav><h2>Study resources</h2><nav class="unit-links" aria-label="Study resources">${navLink('#charts','Evidence library','chart-column')}${navLink('#builder','Create a table or chart','table-2')}${navLink('#more-sources','More Sources','book-marked')}</nav><details class="reading-settings"><summary>Text size</summary><div class="font-buttons" aria-label="Text size">${[[16,'A'],[18,'A+'],[21,'A++']].map(([v,label])=>`<button data-size="${v}" aria-pressed="${state.size===v}" title="${v} pixel reading text">${label}</button>`).join('')}</div></details><div class="sidebar-footer">Version 09 &middot; 2026-27<br>Instructional examples, not scored submissions.<a href="https://explorer.chrisboosalis.com" target="_blank" rel="noreferrer">Open the Equity Gap app ${icon('external-link')}</a></div>`;
  }
  function home(){
    main.innerHTML=window.GUIDE.home();
  }
  function renderSections(u,mode,prefix='section'){
    return u[mode].map((s,i)=>`<section aria-labelledby="${prefix}-${i}"><h2 id="${prefix}-${i}">${s.title}</h2>${s.html}</section>`).join('');
  }
  function unit(u){
    const area=areas.find(a=>a.id===u.area), n=units.filter(x=>x.area===u.area).indexOf(u)+1;
    const pos=units.indexOf(u), prev=units[pos-1],next=units[pos+1];
    main.innerHTML=`<nav class="crumb" aria-label="Breadcrumb"><a href="#home">CalAPA</a><span>/</span><span>${area.title}</span><span>/</span><span>Unit ${n}</span><span>/</span><span>${state.mode==='lecture'?'Lecture':'Worked walkthrough'}</span></nav><header class="unit-header"><p class="kicker">${esc(u.parts)} &middot; ${esc(u.rubrics.startsWith('1.')||u.rubrics.startsWith('2.')||u.rubrics.startsWith('3.')?'Rubrics '+u.rubrics:u.rubrics)}</p><h1>${esc(u.title)}</h1><p class="deck">${esc(u.focus)}</p><div class="tools"><span class="mode-label">${state.mode==='lecture'?'Lecture':'Annotated worked example'}</span><button data-switch-view>${state.mode==='lecture'?'Read the walkthrough':'Read the lecture'}</button><button class="icon-button" data-print title="Print this unit" aria-label="Print this unit">${icon('printer')}</button><button class="icon-button" data-copy-link title="Copy link to this unit" aria-label="Copy link to this unit">${icon('link')}</button><a href="sources/CalAPA_C${u.guide[0]}_AssessmentGuide.pdf#page=${u.guide[1]}" target="_blank" rel="noreferrer">Official guide ${icon('external-link')}</a></div></header><nav class="page-toc" aria-label="On this page">${u[state.mode].map((s,i)=>`<a href="#section-${i}" data-jump="section-${i}">${s.title}</a>`).join('')}</nav><article class="reading">${renderSections(u,state.mode)}<section><h2>Evidence to prepare</h2><p class="note">Personal planning checks. These do not certify rubric scores or submission readiness.</p><div class="checklist">${u.evidence.items.map((item,i)=>`<label><input type="checkbox" data-check="${u.id}:${i}" ${state.checks[u.id+':'+i]?'checked':''}><span>${item}</span></label>`).join('')}</div></section></article><nav class="endnav" aria-label="Unit sequence">${prev?`<a href="${route(prev.id)}">${icon('arrow-left')}<span><small>Previous unit</small>${esc(prev.title)}</span></a>`:'<span></span>'}${next?`<a href="${route(next.id)}"><span><small>Next unit</small>${esc(next.title)}</span>${icon('arrow-right')}</a>`:'<a href="#sources"><span><small>Finish with the evidence map</small>Sources &amp; Templates</span>'+icon('arrow-right')+'</a>'}</nav>`;
  }
  function chartLibrary(id){
    if(!charts[id])id='graduation-gaps';
    main.innerHTML=`<p class="kicker">Jordan High &middot; public evidence</p><h1>Evidence Library</h1><p class="deck">The Equity Gap app's figures, paired with the numbers and source qualifications needed to interpret them.</p><div class="chart-picker" aria-label="Select a chart">${Object.entries(charts).map(([key,c])=>`<button data-chart-select="${key}" aria-pressed="${key===id}">${esc(c.title)}</button>`).join('')}</div><h2>${esc(charts[id].title)}</h2>${chartHTML(id)}<h2>The three-year English Learner graduation record (2023-2025)</h2>${historyHTML()}<p><a href="${route('gap-app','walkthrough')}">Read the chart-to-claim walkthrough</a> &middot; <a href="sources/jordan-evidence.json" download>Download all public evidence and provenance</a></p>`;
  }
  const templateSets={
    1:[['A','Data collection and equity-gap analysis','CalAPA_C1_S1_A_DataCollectionEquityGapAnalysis.docx','5 pages of responses, excluding data tables'],['B','Contributing factors and problem statement','CalAPA_C1_S2_B_ContribFactorsAndProbStatement.docx','5 pages'],['C','School improvement and equity plan','CalAPA_C1_S3_C_PlanSchoolImprovementPromotEquity.docx','5 pages'],['D','Reflection','CalAPA_C1_S4_D_ReflectiveNarrative.docx','5 pages or 5-minute video']],
    2:[['A','Context, focus, community of practice','CalAPA_C2_S1_A_ContextEdFocusCommunityPrac.docx','5 pages'],['B','Planning agenda','CalAPA_C2_S2_B_PlanningMeetingAgenda_OptionalTemplate.docx','Required artifact; optional template'],['C','Planning minutes','CalAPA_C2_S2_C_PlanningMeetingMinutes_OptionalTemplate.docx','Required artifact; optional template'],['D','Problem of practice and strategy','CalAPA_C2_S2_D_ProbPracDescStrategy.docx','4 pages'],['E','Implementation agendas','CalAPA_C2_S3_E_AgendasImplemenationMeetings_OptionalTemplate.docx','At least 3 meetings; one file'],['F','Implementation minutes','CalAPA_C2_S3_F_MinutesImplemenationMeetings_OptionalTemplate.docx','At least 3 meetings; one file'],['G','Key collaborative products',null,'One file, up to 10 pages'],['H','Implementation meeting clips',null,'3 clips, up to 5 minutes each'],['I','Implementation commentary','CalAPA_C2_S3_I_CommentaryImplementationMeetings.docx','8 pages or 10 minutes verbal/ASL'],['J','Reflection','CalAPA_C2_S4_J_ReflectiveNarrative.docx','4 pages or 5 minutes verbal/ASL']],
    3:[['A','Coaching practices and volunteer teacher','CalAPA_C3_S1_A_CoachingObsFeedbackPracVolTeacher.docx','5 pages'],['B','Classroom, lesson, and observation','CalAPA_C3_S2_B_ClassroomContextLessonObservation.docx','4 pages'],['C','Teacher lesson plan',null,'Includes student work-product description'],['D','Pre-observation meeting clips',null,'2 clips, up to 6 minutes each'],['E','Pre-observation commentary','CalAPA_C3_S2_E_CommentaryPreObservationMeeting.docx','8 pages or 10 minutes verbal/ASL'],['F','Observation notes',null,'CSTP-focused notes/forms in one file'],['G','Student work',null,'At least one example from the lesson in one file'],['H','Post-observation meeting clips',null,'1-3 clips; at least 1 minute each; up to 15 minutes total'],['I','Post-observation commentary','CalAPA_C3_S3_I_CommentaryPostObservationMeeting.docx','8 pages or 10 minutes verbal/ASL'],['J','Reflection','CalAPA_C3_S4_J_ReflectiveNarrative.docx','4 pages or 6 minutes verbal/ASL']]
  };
  function sources(){
    main.innerHTML=`<p class="kicker">Requirements and evidence</p><h1>Saved Version 09 guides and templates</h1><p class="deck">The official guides establish the requirements. The walkthroughs explain the leadership reasoning with an original teaching case.</p><div class="reading"><section><h2>Submission evidence, part by part</h2><p>Files below were extracted unchanged from the supplied 2026-27 Version 09 packages. The Commission on Teacher Credentialing owns the official guides and templates. Confirm the applicable version through your preparation program and <a href="https://www.ctcexams.nesinc.com/TestView.aspx?f=HTML_FRAG/CalAPA_TestPage.html" target="_blank" rel="noreferrer">the official CalAPA site</a>.</p>${[1,2,3].map(c=>`<details ${c===1?'open':''}><summary>Cycle ${c}: guide and all required parts</summary><p><a href="sources/CalAPA_C${c}_AssessmentGuide.pdf" target="_blank" rel="noreferrer">Read the Cycle ${c} assessment guide</a></p><div class="table-scroll"><table><thead><tr><th>Part</th><th>Evidence</th><th>Response limit / note</th></tr></thead><tbody>${templateSets[c].map(([part,name,file,note])=>`<tr><td>${part}</td><td>${file?`<a href="sources/${file}" download>${name}</a>`:name+'<br><small>Candidate-produced evidence; no blank template in the package.</small>'}</td><td>${note}</td></tr>`).join('')}</tbody></table></div><button data-print-area="c${c}">${icon('printer')} Print the Cycle ${c} worked example</button></details>`).join('')}</section><section><h2>Recording and authorship</h2><p>The fictional transcripts illustrate leadership moves and commentary. They are not scripts for staging submitted meetings. Real Cycle 2 meetings must be authentic, and actual Cycle 3 evidence must document the candidate's coaching, observation, and conversation. Obtain required permissions and follow site recording policies.</p><p>Use the original template text and formatting. Redact actual school and person names and identifying information as directed. Public school identity is retained in this teaching case to verify the charts. Candidates author their own submissions; the teaching models are not submission files or assessor-scored exemplars.</p><p>Written formats in the guides are DOCX, ODT, or PDF; video formats include MP4 and the other formats listed in the specifications. Required uploads cannot be replaced by hyperlinks. Refer to the original guides for translation provisions, exact prompts, and complete file specifications.</p></section><section><h2>Public data and interpretation</h2><ul class="source-list"><li><a href="https://explorer.chrisboosalis.com" target="_blank" rel="noreferrer">Equity Gap app</a><small>Select Jordan High, Los Angeles Unified, CDS 19647331934454. Use Full Report, All Indicators, CalAPA Cycle 1 Support, and Equity Timeline Explorer.</small></li><li><a href="sources/jordan-evidence.json" download>Jordan High evidence and provenance snapshot</a><small>Prepared October 6, 2026, from the Equity Gap app's stored public data and charts. Data remain public-source observations; no private student records were imported.</small></li><li><a href="sources/010_full_report_jordan_high.txt" download>Saved Jordan High Full Report text</a><small>App wording as captured October 6, 2026. Some wording differs from the clarified language on this site.</small></li><li><a href="https://www.cde.ca.gov/ta/ac/cm/gradindicator24.asp" target="_blank" rel="noreferrer">CDE graduation indicator</a><small>Check the accountability denominator, fifth-year contribution, and source-year definitions.</small></li><li><a href="https://www.cde.ca.gov/ta/ac/cm/dashboardchronic.asp" target="_blank" rel="noreferrer">CDE chronic absenteeism indicator</a><small>Dashboard TK-8 coverage differs from high-school DataQuest attendance.</small></li><li><a href="https://www.cde.ca.gov/ta/ac/cm/dashboardacad.asp" target="_blank" rel="noreferrer">CDE academic indicator</a><small>Dashboard Distance from Standard differs from Smarter Balanced percent meeting or exceeding standard.</small></li></ul></section><section><h2>Research and professional standards</h2><ul class="source-list"><li><a href="https://ies.ed.gov/ncee/wwc/PracticeGuide/24/Published" target="_blank" rel="noreferrer">What Works Clearinghouse. Preventing Dropout in Secondary Schools (2017).</a><small>Informs the inquiry into monitoring and individualized response. Recommendations differ in evidence strength and require attention to local fit.</small></li><li><a href="https://ies.ed.gov/ncee/wwc/Docs/PracticeGuide/wwc_secondary_writing_110116.pdf" target="_blank" rel="noreferrer">What Works Clearinghouse. Teaching Secondary Students to Write Effectively (2016).</a><small>Informs the model-practice-reflect routine and feedback based on student writing. The fictional cross-subject adaptation is not itself an evaluated intervention.</small></li><li><a href="https://docs.ctc.ca.gov/Document/Download/30328" target="_blank" rel="noreferrer">California Standards for the Teaching Profession (2024).</a><small>Cycle 3 uses CSTP 5A and 5B as its fictional co-selected focus. Consult official element wording and the framework applicable at your site.</small></li></ul></section><section><h2>How the teaching case was developed</h2><p>The course follows the Intro to Research organization: content areas, units, a lecture and a worked walkthrough, and a continuous reading sequence. Public charts use the Equity Gap app's own rendering function. Local qualitative evidence, classroom work, meetings, feedback, and implementation results were authored as fictional examples.</p><p>The instructor sets the instructional direction and reviews the material. OpenAI Codex assisted in organizing and developing this site. The models make reasoning explicit without claiming official scoring or actual implementation at Jordan High.</p></section></div>`;
  }
  function moreSources(){
    return window.LEARNING_SUPPORT.resources(`<p class="kicker">Verified links &middot; reviewed October 8, 2026</p><h1>More Sources</h1><p class="deck">Current official CalAPA documents first, followed by CTC videos and clearly labeled supplemental program resources.</p><div class="reading"><section><h2>Start with the current official materials</h2><p>For submissions after July 2, 2026, use the 2026-27 <strong>Version 09</strong> guides, templates, and rubrics. The cycle folders below are the Commission's current download locations.</p><ul class="source-list"><li><a href="https://ctcexams.nesinc.com/TestView.aspx?f=HTML_FRAG/CalAPA_TestPage.html" target="_blank" rel="noreferrer">CalAPA home and current-year notice</a><small>Official assessment overview, fees, deadlines, results, and links to current policies and preparation materials.</small></li><li><a href="https://www.ctc.ca.gov/performance-assessment/resources/" target="_blank" rel="noreferrer">CTC Performance Assessment Resources</a><small>The Commission's index for the 2026-27 Version 09 cycle folders.</small></li><li><a href="https://docs.ctc.ca.gov/DocumentLookup/5/Folder/1989" target="_blank" rel="noreferrer">Cycle 1 assessment guide and Templates A-D</a><small>Analyzing Data to Inform School Improvement and Promote Equity.</small></li><li><a href="https://docs.ctc.ca.gov/DocumentLookup/5/Folder/1990" target="_blank" rel="noreferrer">Cycle 2 assessment guide and Templates A-F, I, and J</a><small>Facilitating Communities of Practice.</small></li><li><a href="https://docs.ctc.ca.gov/DocumentLookup/5/Folder/1991" target="_blank" rel="noreferrer">Cycle 3 assessment guide and Templates A, B, E, I, and J</a><small>Supporting Teacher Growth.</small></li></ul></section><section><h2>Permissions, confidentiality, and authorship</h2><ul class="source-list"><li><a href="https://www.ctcexams.nesinc.com/Content/Docs/CalAPASampleConsentForm_ParentGuardianFamily.pdf" target="_blank" rel="noreferrer">Sample Parent/Guardian/Family Consent Form</a><small>Use when the school or district does not already have the needed permission on file; also follow local program and district requirements.</small></li><li><a href="https://www.ctcexams.nesinc.com/Content/Docs/CalAPASampleConsentForm_VolunteerEducator.pdf" target="_blank" rel="noreferrer">Sample Volunteer Educator Consent Form</a><small>Covers participating adults, including the volunteer teacher and educators appearing in CalAPA recordings.</small></li><li><a href="https://www.ctcexams.nesinc.com/TestView.aspx?f=CACBT_TestingPolicies_CalAPA.html" target="_blank" rel="noreferrer">Assessment policies and candidate confidentiality guidelines</a><small>Explains permissions, redaction, secure storage, authorized access, and the prohibition on posting candidate recordings publicly.</small></li><li><a href="https://www.ctcexams.nesinc.com/TestView.aspx?f=CACBT_TestPolicies_CalAPA.html" target="_blank" rel="noreferrer">Rules of Participation</a><small>Covers candidate authorship, permitted evidence, permissions, confidentiality, and the terms accepted at registration.</small></li><li><a href="https://www.ctcexams.nesinc.com/TestView.aspx?f=CACBT_Faculty_CalAPA.html" target="_blank" rel="noreferrer">Acceptable and unacceptable support</a><small>Clarifies what faculty and peers may explain, discuss, and review without writing or selecting evidence for a candidate.</small></li></ul></section><section><h2>Submission and technical help</h2><ul class="source-list"><li><a href="https://www.ctcexams.nesinc.com/TestView.aspx?f=CACBT_SubmissionRequirementsConditionCodes_CalAPA.html" target="_blank" rel="noreferrer">Submission Requirements and Condition Codes</a><small>Use before uploading to check required evidence, file readability, video and audio, page and time limits, and common unscorable conditions.</small></li><li><a href="https://www.ctcexams.nesinc.com/TestView.aspx?f=HTML_FRAG/CalAPA_PrepMaterials.html" target="_blank" rel="noreferrer">CalAPA preparation materials</a><small>Video preparation, file formats, compression, registration, ePortfolio, CAPE, and CSTP links.</small></li><li><a href="https://www.ctcexams.nesinc.com/Content/Docs/RegistrationGuideCalAPA.pdf" target="_blank" rel="noreferrer">Candidate Guide to CalAPA Registration</a><small>Walkthrough for account creation, cycle registration, payment, and entry into the ePortfolio system.</small></li><li><a href="https://www.ctcexams.nesinc.com/Content/Docs/UsingThePearsonSystemCalAPA.pdf" target="_blank" rel="noreferrer">Candidate Guide to the Pearson ePortfolio System</a><small>Downloading templates, uploading and labeling evidence, reviewing files, and submitting a complete cycle.</small></li><li><a href="https://www.ctcexams.nesinc.com/TestView.aspx?f=CACBT_GuidelinesForOnlineSetting_CalAPA.html" target="_blank" rel="noreferrer">Guidelines for an online setting</a><small>Recording, consent, participation, agendas, minutes, and evidence expectations when meetings or coaching occur online.</small></li><li><a href="https://www.ctcexams.nesinc.com/Content/HTML_FRAG/CACBTRB_ResultsDates_CalAPA.html" target="_blank" rel="noreferrer">2026-27 submission and reporting dates</a><small>Official deadlines and score-reporting dates.</small></li></ul></section><section><h2>Professional standards</h2><ul class="source-list"><li><a href="https://docs.ctc.ca.gov/Document/Download/30419" target="_blank" rel="noreferrer">California Administrator Performance Expectations and program standards</a><small>The CAPE appear in Appendix B and provide the leadership-performance foundation for CalAPA.</small></li><li><a href="https://docs.ctc.ca.gov/Document/Download/30328" target="_blank" rel="noreferrer">California Standards for the Teaching Profession (2024)</a><small>The current CSTP resource used when Cycle 3 candidates and volunteer teachers select an observation focus.</small></li></ul></section><section><h2>Current CTC video collection</h2><p>These videos are hosted by the California Commission on Teacher Credentialing. The three deep dives below address Version 09. Older videos in the larger playlist can still help with concepts, but their templates, labels, and limits may no longer match the current assessment.</p><ul class="source-list"><li><a href="https://www.youtube.com/playlist?list=PLhOCkXWD9rQcQpV8rfavfUJ-r-d1A68jh" target="_blank" rel="noreferrer">CTC Performance Assessment YouTube playlist</a><small>The complete Commission playlist for CalAPA, CalTPA, and EdSp CalTPA.</small></li><li><a href="https://www.youtube.com/watch?v=Ki6q2tBfWpo" target="_blank" rel="noreferrer">CalAPA Cycle 1 Deep Dive</a><small>Recorded August 12, 2026; walks through the current Cycle 1 structure and evidence.</small></li><li><a href="https://www.youtube.com/watch?v=llnn6B7z290" target="_blank" rel="noreferrer">CalAPA Cycle 2: Facilitating Communities of Practice, Version 9 Deep Dive</a><small>Current Cycle 2 explanation from the CTC Performance Assessment Team and lead assessors.</small></li><li><a href="https://www.youtube.com/watch?v=BK6O8nwuBxg" target="_blank" rel="noreferrer">Version 9 CalAPA Cycle 3 Deep Dive</a><small>Current Cycle 3 explanation of the coaching cycle, evidence, and rubrics.</small></li><li><a href="https://www.youtube.com/watch?v=LYdBHjccNnY" target="_blank" rel="noreferrer">Identifying the Equity Gap and Analyzing Data</a><small>A 2026 CalAPA Digging Deeper session focused on the opening Cycle 1 inquiry.</small></li><li><a href="https://www.youtube.com/watch?v=53qiuIwfY9A" target="_blank" rel="noreferrer">Acceptable Supports for Performance Assessment, 2026-27</a><small>Current boundaries for candidate, faculty, and peer support.</small></li></ul></section><section><h2>National University and other program perspectives</h2><ul class="source-list"><li><a href="https://docs.ctc.ca.gov/Document/Download/30556" target="_blank" rel="noreferrer">CTC conference session directory: Supporting PASC Candidates</a><small>Describes a National University session by Tish Nilsen, Dina Pacis, and Donna Elder about its CalAPA support site and monthly credentialing-support meetings. This is a program perspective, not the official Version 09 guide.</small></li><li><a href="https://drive.google.com/drive/u/0/folders/1fdc-8jw5XH74T7BNQrR8NCIsi7jCEiQv" target="_blank" rel="noreferrer">National University conference materials</a><small>The public materials folder linked by the CTC session directory. Access may depend on the owner's current sharing settings.</small></li><li><a href="https://www.youtube.com/watch?v=8o6FGWG8H8E" target="_blank" rel="noreferrer">Engineering Excellence: Building a System of Support for CalAPA Success and Program Improvement</a><small>A 2026 CTC-hosted MFIC presentation offering a practitioner and program-support perspective.</small></li></ul><p class="fiction"><strong>Why no public candidate submission clips are listed:</strong> searches also surface videos uploaded by individual candidates. Current CTC policy says candidate recordings must not be posted in public locations such as YouTube. Those clips are not appropriate course resources, and they may reflect obsolete requirements.</p></section></div>`);
  }
  window.CURRENT_RESOURCES={render:moreSources};
  function render(){
    const hash=location.hash||'#home';const parts=hash.slice(1).split('/');currentUnit=null;
    if(parts[0]==='builder'){location.replace('#home');return;}
    if(parts[0]==='thread'){location.replace('#home/common-thread');return;}
    if(parts[0]==='equity-gap-help'){state.area='c1';save();}
    main.classList.toggle('cycle1-main',parts[0]==='cycle'&&['c1','c2','c3'].includes(parts[1]));
    main.classList.toggle('equity-help-main',parts[0]==='equity-gap-help');
    if(['cycle','connections','app-reference','gap','literature'].includes(parts[0])){state.area=['c1','c2','c3'].includes(parts[1])?parts[1]:'c1';save();}
    if(parts[0]==='sources'&&areas.some(a=>a.id===parts[1])){state.area=parts[1];save();}
    if(parts[0]==='home'||!location.hash){state.area='start';save();}
    if(parts[0]==='unit'){
      currentUnit=units.find(u=>u.id===parts[1])||null;
      if(currentUnit){state.area=currentUnit.area;state.mode=parts[2]==='walkthrough'?'walkthrough':'lecture';save();unit(currentUnit);}else home();
    }else if(parts[0]==='source'&&parts[1]==='framework')main.innerHTML=window.GAP_READER.render('framework');else if(parts[0]==='source')main.innerHTML=window.GAP_READER.render(parts[1]);else if(parts[0]==='connections')main.innerHTML=window.TUTORIAL.render(parts[1]);else if(parts[0]==='gap')main.innerHTML=window.MENTOR.gap(parts[1]);else if(parts[0]==='literature'||parts[0]==='research-reading')main.innerHTML=window.MENTOR.literature(parts[1]||state.area);else if(parts[0]==='app-reference')main.innerHTML=window.CONNECTIONS.render(parts[1]);else if(parts[0]==='recording')main.innerHTML=window.CONNECTIONS.recording();else if(parts[0]==='builder')builder(parts[1]);else if(parts[0]==='charts')chartLibrary(parts[1]);else if(parts[0]==='sources')sources();else if(parts[0]==='more-sources'||parts[0]==='notes')main.innerHTML=moreSources();else home();
    document.documentElement.style.setProperty('--text-size',state.size+'px');
    sidebarHTML();
    sidebar.querySelector('a[href="#builder"]')?.remove();
    const overview=sidebar.querySelector('.unit-links a');
    if(state.area!=='start')overview.href=`#cycle/${state.area}`;
    if(location.hash===overview.getAttribute('href'))overview.setAttribute('aria-current','page');
    else overview.removeAttribute('aria-current');
    const study=sidebar.querySelector('[aria-label="Study resources"]');
    study.insertAdjacentHTML('afterbegin',`<a class="unit-link" href="#readiness">${icon('list-checks')}<span>Requirements check</span></a>`);
    const textSize=sidebar.querySelector('.font-buttons');
    const readingSettings=sidebar.querySelector('.reading-settings');
    const textSizeControls=document.createElement('div');
    textSizeControls.className='text-size-controls';
    textSizeControls.innerHTML='<p id="text-size-label">Text size</p>';
    textSize.setAttribute('role','group');
    textSize.setAttribute('aria-labelledby','text-size-label');
    textSize.removeAttribute('aria-label');
    textSizeControls.append(textSize);
    readingSettings.remove();
    sidebar.prepend(textSizeControls);
    if(parts[0]==='cycle')main.innerHTML=window.GUIDE.cycle(state.area,templateSets);
    if(parts[0]==='equity-gap-help')main.innerHTML=window.EQUITY_GAP_HELP.render();
    if(['c1','c2','c3'].includes(state.area)){
      ['investigate','plan','act','reflect'].forEach((step,i)=>{
        const link=sidebar.querySelector(`a[href^="#unit/${state.area}-${step}/"]`);
        if(!link)return;
        const part={c1:'abcd',c2:'abej',c3:'abfj'}[state.area][i];
        link.href=`#cycle/${state.area}/part-${part}`;
        link.removeAttribute('aria-current');
        if(location.hash===link.getAttribute('href'))link.setAttribute('aria-current','page');
      });
      study.insertAdjacentHTML('afterbegin',`<a class="unit-link" href="#equity-gap-help">${icon('chart-no-axes-combined')}<span>Equity Gap Help</span></a>`);
    }
    if(main.classList.contains('cycle1-main')){
      main.querySelector('.guide-heading').insertAdjacentHTML('beforeend',`<div class="tools"><button class="icon-button" data-print title="Print Cycle ${state.area.slice(1)}" aria-label="Print Cycle ${state.area.slice(1)}">${icon('printer')}</button></div>`);
    }
    if(parts[0]==='readiness')main.innerHTML=window.GUIDE.readiness();
    if(parts[0]==='search'){
      let query='';try{query=decodeURIComponent(parts.slice(1).join('/'));}catch{query=parts.slice(1).join('/');}
      main.innerHTML=window.GUIDE.search(query.slice(0,180));
    }
    if(currentUnit){
      const cycle=currentUnit.area==='start'?'c1':currentUnit.area;
      main.querySelector('.crumb span:last-child').textContent=state.mode==='lecture'?'Overview':'Worked response';
      main.querySelector('[data-switch-view]').remove();
      main.querySelector('.mode-label').remove();
      const toc=main.querySelector('.page-toc');
      const contents=document.createElement('details');contents.className='contents-index';
      contents.innerHTML='<summary>On this page</summary>';toc.replaceWith(contents);contents.append(toc);
      main.querySelector('.unit-header').insertAdjacentHTML('beforeend',`<p class="connection-context"><a href="#gap/${cycle}">How the Gap app supports ${currentUnit.id==='orientation'?'the three cycles':'this cycle'} ${icon('arrow-right')}</a></p>`);
      if(currentUnit.area==='c1'){
        const part='abcd'[['investigate','plan','act','reflect'].indexOf(currentUnit.id.split('-')[1])];
        main.querySelector('.unit-header').insertAdjacentHTML('beforeend',`<p><a href="#cycle/c1/part-${part}">Read the revised Part ${part.toUpperCase()} guidance, original template, and complete rubrics</a></p>`);
      }
      main.querySelector('.unit-header').insertAdjacentHTML('afterend',`<nav class="view-tabs" aria-label="Reading view"><a href="${route(currentUnit.id,'lecture')}" ${state.mode==='lecture'?'aria-current="page"':''}>Overview</a><a href="${route(currentUnit.id,'walkthrough')}" ${state.mode==='walkthrough'?'aria-current="page"':''}>Worked response</a></nav>`);
      main.querySelector('.reading').insertAdjacentHTML('afterbegin',`<details class="case-prompt-map"><summary>Read the teaching case against the template prompts</summary><p>Case-specific illustrations, not instructions to select this school's topic or copy these responses. Use the original template for every prompt.</p>${window.MENTOR.promptGuide(currentUnit,state.mode)}</details>`);
      if(currentUnit.area!=='start'){
        main.querySelectorAll('.crumb span')[3].textContent=`Step ${window.GUIDE_CONTENT.steps[currentUnit.id].step}`;
        main.querySelector('.unit-header a[href^="sources/CalAPA_"]').href=`sources/CalAPA_C${cycle.slice(1)}_AssessmentGuide.pdf#page=${window.GUIDE_CONTENT.steps[currentUnit.id].pages[0]}`;
        main.querySelector('.reading').insertAdjacentHTML('afterbegin',window.GUIDE.stepLead(currentUnit,templateSets));
        main.querySelector('.reading').insertAdjacentHTML('beforeend',window.GUIDE.stepEnd(currentUnit));
        if(state.mode==='walkthrough'){
          main.querySelector('.view-tabs').insertAdjacentHTML('afterend',`<p class="example-boundary"><strong>Teaching excerpt, not a complete submission.</strong> ${esc(window.GUIDE_CONTENT.steps[currentUnit.id].exampleLimit)} Public figures are identified separately from fictional meetings, quotations, work, and feedback. The excerpts are not scored exemplars or scripts for assessed meetings.</p>`);
          const summary=main.querySelector('.requirement-summary'),review=document.createElement('details');
          review.className='task-review';review.innerHTML='<summary>Review the task and required evidence</summary>';
          summary.replaceWith(review);review.append(summary);
        }
      }
      if(currentUnit.area!=='start')main.querySelector('.reading').insertAdjacentHTML('beforeend',window.MENTOR.researchBlock(cycle));
    }
    if(parts[0]==='connections')main.querySelector('.reading>section').insertAdjacentHTML('afterend',window.MENTOR.cycleMap(state.area));
    if(parts[0]==='sources'&&parts[1])main.querySelectorAll('details').forEach(d=>{if(d.querySelector('summary')?.textContent.startsWith('Cycle '))d.open=d.querySelector('summary').textContent.startsWith('Cycle '+parts[1].slice(1));});
    if(parts[0]==='charts'){
      const picker=main.querySelector('.chart-picker');
      const selected=picker.querySelector('[aria-pressed=true]').dataset.chartSelect;
      picker.innerHTML=`<label for="chartSelect">Evidence figure</label><br><select id="chartSelect">${Object.entries(charts).map(([key,c])=>`<option value="${key}" ${selected===key?'selected':''}>${esc(c.title)}</option>`).join('')}</select>`;
    }
    main.querySelectorAll('a[href="#research-reading"]').forEach(a=>{a.href=`#literature/${state.area==='start'?'c1':state.area}`;a.textContent='Using literature in this cycle';});
    if(parts[0]==='app-reference')main.querySelector('.reading').insertAdjacentHTML('afterbegin',window.GAP_READER.intro());
    if(parts[0]!=='source')main.querySelectorAll('a[href^="sources/"]').forEach(a=>{const file=a.getAttribute('href').slice(8),entry=Object.entries(window.SOURCE_READINGS).find(([,s])=>s.file===file);if(entry){a.href=`#source/${entry[0]}`;a.removeAttribute('download');a.removeAttribute('target');if(/download|saved.*text/i.test(a.textContent))a.textContent='Read the saved '+(entry[0]==='report'?'Full Report':'source section');}});
    const activeTop=parts[0]==='equity-gap-help'?'#equity-gap-help':['more-sources','notes'].includes(parts[0])?'#more-sources':state.area==='start'?'#home':`#cycle/${state.area}`;
    document.querySelectorAll('.topbar nav a').forEach(a=>{if(a.getAttribute('href')===activeTop)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
    if(parts[0]==='glossary')main.innerHTML=window.LEARNING_SUPPORT.glossary();
    if(parts[0]==='cycle')main.querySelector('#fictional-case')?.insertAdjacentHTML('beforeend',window.LEARNING_SUPPORT.evidenceMap(state.area));
    if(['unit','connections','app-reference','gap'].includes(parts[0]))main.querySelector('.reading')?.insertAdjacentHTML('afterbegin',window.LEARNING_SUPPORT.caseNotice(state.area==='start'?'c1':state.area));
    if(['readiness','recording'].includes(parts[0]))main.querySelector('.reading')?.insertAdjacentHTML('afterbegin',window.LEARNING_SUPPORT.privacy());
    if(parts[0]==='readiness')main.querySelector('.reading')?.insertAdjacentHTML('beforeend',window.LEARNING_SUPPORT.resourceTypes());
    if(['home','cycle','equity-gap-help'].includes(parts[0]))window.LEARNING_SUPPORT.linkFirstTerms(main);
    hydrate();document.title=(main.querySelector('h1')?.textContent||'CalAPA Help')+' | CalAPA Help';
    if(['home','connections','app-reference','source'].includes(parts[0])||!location.hash)main.querySelectorAll('.chart').forEach(figure=>{figure.querySelectorAll('details').forEach(detail=>detail.open=true);const wrapper=figure.parentElement.closest('details');if(wrapper)wrapper.open=true;});
    if(hash!==lastRoute){window.scrollTo(0,0);sidebar.classList.remove('open');document.querySelector('#menuBtn').setAttribute('aria-expanded','false');if(lastRoute)main.focus({preventScroll:true});lastRoute=hash;}
    if((['cycle','source'].includes(parts[0])&&parts[2])||(['home','equity-gap-help','glossary','more-sources','readiness'].includes(parts[0])&&parts[1])){
      const target=document.getElementById(['cycle','source'].includes(parts[0])?parts[2]:parts[1]);
      if(target&&main.contains(target)){for(let parent=target.parentElement;parent&&parent!==main;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;target.tabIndex=-1;target.scrollIntoView();target.focus({preventScroll:true});}
    }
  }
  function printArea(area){
    const selected=units.filter(u=>u.area===area);if(!selected.length)return;
    main.innerHTML=`<p class="print-only">CalAPA teaching model | Version 09 | Prepared October 6, 2026</p><p class="fiction">Public Jordan High figures and fictional Harbor High extensions. Not an assessor-scored submission. Meetings, observations, quotations, work, and implementation results are teaching examples.</p>${selected.map((u,j)=>`<div class="print-unit"><header class="unit-header"><p class="kicker">${esc(u.parts)} &middot; Rubrics ${esc(u.rubrics)}</p><h1>${esc(u.title)}</h1></header><article class="reading">${renderSections(u,'walkthrough',`print-${j}`)}</article></div>`).join('')}<p class="source-note">Official requirements: supplied CalAPA Cycle ${area.slice(1)} Version 09 guide. Public data: Equity Gap app Jordan High snapshot, October 6, 2026. Research: WWC Preventing Dropout in Secondary Schools (2017); Teaching Secondary Students to Write Effectively (2016). Coaching focus: 2024 CSTP 5A and 5B. Full references and original source tables are in Sources &amp; Templates.</p><div class="tools"><button data-return>Return to course</button></div>`;
    hydrate();Promise.all([...main.querySelectorAll('img')].map(img=>img.decode().catch(()=>{}))).then(()=>window.print());
  }
  document.addEventListener('click',async event=>{
    const el=event.target.closest('button,a');if(!el)return;
    if(el.tagName==='A'&&el.getAttribute('href')===location.hash&&(location.hash.startsWith('#cycle/')||location.hash.startsWith('#equity-gap-help'))){
      event.preventDefault();const id=location.hash.split('/')[location.hash.startsWith('#cycle/')?2:1],target=id?document.getElementById(id):main;
      if(target&&main.contains(target)){target.tabIndex=-1;target.scrollIntoView();target.focus({preventScroll:true});if(!id)window.scrollTo(0,0);}return;
    }
    if(el.hasAttribute('data-builder-generate')){generateEvidence();return;}
    if(el.hasAttribute('data-builder-reset')){builderState=initialBuilder(builderState.id);builder(builderState.id);hydrate();return;}
    if(el.hasAttribute('data-builder-add')){if(builderState.rows.length<12){builderState.rows.push({label:'',value:null});builderState.edited=true;builderState.generated=false;builder(builderState.id);hydrate();}return;}
    if(el.hasAttribute('data-builder-remove')){if(builderState.rows.length>1){builderState.rows.splice(Number(el.dataset.builderRemove),1);builderState.edited=true;builderState.generated=false;builder(builderState.id);hydrate();}return;}
    if(el.hasAttribute('data-builder-png')){const canvas=document.querySelector('#generatedCanvas');if(canvas&&builderState.generated){const a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download='calapa-evidence-chart.png';a.click();}return;}
    if(el.hasAttribute('data-builder-csv')){if(!builderState.generated)return;const safeLabel=s=>'"'+String(s).replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';const lines=[['Category / year',builderState.gap?'Gap (points)':'Rate (%)','Data status'].map(safeLabel).join(',')];for(const r of builderState.rows)lines.push([safeLabel(r.label),r.value===null?'':String(r.value),safeLabel(builderState.edited?'User-entered; not verified':'Public snapshot 2026-10-06')].join(','));download('calapa-evidence-table.csv',lines.join('\r\n'),'text/csv;charset=utf-8');return;}
    if(el.matches('[data-jump]')){event.preventDefault();document.getElementById(el.dataset.jump)?.scrollIntoView();return;}
    if(el.matches('.skip')){event.preventDefault();main.focus();return;}
    if(el.id==='menuBtn'){const open=sidebar.classList.toggle('open');el.setAttribute('aria-expanded',String(open));return;}
    if(el.dataset.mode){state.mode=el.dataset.mode;save();location.hash=route(currentUnit?.id||units.find(u=>u.area===state.area).id);return;}
    if(el.dataset.size){state.size=Number(el.dataset.size);save();document.documentElement.style.setProperty('--text-size',state.size+'px');sidebar.querySelectorAll('[data-size]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.size)===state.size)));return;}
    if(el.hasAttribute('data-switch-view')){location.hash=route(currentUnit.id,state.mode==='lecture'?'walkthrough':'lecture');return;}
    if(el.dataset.chartSelect){location.hash='#charts/'+el.dataset.chartSelect;return;}
    if(el.hasAttribute('data-map-expand')||el.hasAttribute('data-figure-expand')){
      const isFigure=el.hasAttribute('data-figure-expand');
      const img=document.querySelector('#largeChart');
      const sourceImage=el.querySelector('img');
      img.style.width='';
      img.src=sourceImage.currentSrc||sourceImage.src;
      img.alt=sourceImage.alt;
      document.querySelector('#largeCaption').textContent=isFigure?el.closest('figure').querySelector('figcaption').textContent:'CalAPA assessment map: three leadership cycles, each with its own evidence and rubrics.';
      const dialog=document.querySelector('#imageDialog');
      dialog.dataset.imageKind=isFigure?'image':'map';
      dialog.classList.remove('map-zoomed');
      dialog.classList.add('assessment-map-dialog');
      const zoom=document.querySelector('#mapZoom');zoom.hidden=false;zoom.setAttribute('aria-pressed','false');zoom.setAttribute('aria-label','Zoom map to full resolution');zoom.title='Zoom map to full resolution';zoom.innerHTML=icon('zoom-in');window.lucide?.createIcons();
      dialog.setAttribute('aria-label','CalAPA assessment map');
      if(isFigure){zoom.setAttribute('aria-label','Zoom image to full resolution');zoom.title='Zoom image to full resolution';dialog.setAttribute('aria-label',el.dataset.imageTitle);}
      dialog.querySelector('.close-dialog').setAttribute('aria-label','Close image');
      dialog.querySelector('.close-dialog').title='Close image';
      dialog.showModal();return;
    }
    if(el.id==='mapZoom'){
      const dialog=document.querySelector('#imageDialog'),img=document.querySelector('#largeChart');
      const zoomed=dialog.classList.toggle('map-zoomed');img.style.width=zoomed?img.naturalWidth+'px':'';
      const kind=dialog.dataset.imageKind||'map';const label=zoomed?`Fit ${kind} to window`:`Zoom ${kind} to full resolution`;el.setAttribute('aria-pressed',String(zoomed));el.setAttribute('aria-label',label);el.title=label;el.innerHTML=icon(zoomed?'minimize':'zoom-in');window.lucide?.createIcons();return;
    }
    if(el.dataset.zoom){const c=charts[el.dataset.zoom];const img=document.querySelector('#largeChart');img.style.width='';img.src='assets/'+c.file;img.alt=c.caption;document.querySelector('#mapZoom').hidden=true;document.querySelector('#largeCaption').textContent=c.caption;const dialog=document.querySelector('#imageDialog');dialog.classList.remove('assessment-map-dialog','map-zoomed');dialog.setAttribute('aria-label','Expanded chart');dialog.showModal();return;}
    if(el.matches('.close-dialog')){document.querySelector('#imageDialog').close();return;}
    if(el.hasAttribute('data-copy-link')){try{await navigator.clipboard.writeText(location.href);notify('Unit link copied.');}catch{notify('Copy the unit URL from your browser address bar.');}return;}
    if(el.hasAttribute('data-print')){await Promise.all([...main.querySelectorAll('img')].map(img=>{img.loading='eager';return img.decode().catch(()=>{});}));window.print();return;}
    if(el.dataset.printArea){printArea(el.dataset.printArea);return;}
    if(el.hasAttribute('data-return')){render();return;}
  });
  document.addEventListener('input',event=>{const el=event.target;if(el.matches('[data-builder-label]')){builderState.rows[Number(el.dataset.builderLabel)].label=el.value;dirtyBuilder();}if(el.matches('[data-builder-value]')){builderState.rows[Number(el.dataset.builderValue)].value=el.validity.badInput?NaN:el.value===''?null:Number(el.value);dirtyBuilder();}if(el.id==='builderTitle'){builderState.title=el.value;dirtyBuilder();}});
  document.addEventListener('change',async event=>{
    const el=event.target;
    if(el.id==='builderExample'){location.hash='#builder/'+el.value;return;}
    if(el.id==='chartSelect'){location.hash='#charts/'+el.value;return;}
    if(el.id==='builderKind'){builderState.kind=el.value;dirtyBuilder();return;}
    if(el.id==='areaSelect'){state.area=el.value;save();location.hash=el.value==='start'?'#home':`#cycle/${el.value}`;}
    if(el.dataset.check){state.checks[el.dataset.check]=el.checked;save();}
  });
  document.querySelector('#imageDialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close();}});
  document.addEventListener('submit',event=>{if(event.target.matches('[data-guide-search]')){event.preventDefault();const query=new FormData(event.target).get('q')||'';location.hash='#search/'+encodeURIComponent(String(query).trim().slice(0,180));}});
  window.addEventListener('hashchange',render);
  const header=document.querySelector('.topbar');
  const sizeHeader=()=>document.documentElement.style.setProperty('--header-height',header.getBoundingClientRect().height+'px');
  new ResizeObserver(sizeHeader).observe(header);sizeHeader();
  window.addEventListener('afterprint',render);
  render();
})();
